import org.eclipse.swt.widgets.Label;

public class TestClass {
    Label fLabel;

    public TestClass(Label label) {
        this.fLabel = label;
    }

    public void setLabelColor() {
        if (fLabel == null) return;
        Display display = fLabel.getDisplay();
        Color color = fLabel.getParent().getForeground();
        fLabel.setForeground(color);
    }

    public void anotherMethod() {
        System.out.println(fLabel.getText());
    }
}

