package test;

import org.eclipse.swt.SWT;
import org.eclipse.swt.graphics.Color;
import org.eclipse.swt.widgets.Composite;
import org.eclipse.swt.widgets.Display;
import org.eclipse.swt.widgets.Label;

public class NegativeTestClass {
    Composite fComposite;

    public NegativeTestClass(Composite composite) {
        this.fComposite = composite;
    }

    public void setCompositeColor() {
        if (fComposite == null) return;
        Display display = fComposite.getDisplay();
        // This call should NOT be changed (different color constant)
        Color color1 = display.getSystemColor(SWT.COLOR_RED);
        fComposite.setBackground(color1);

        // This call should NOT be changed (target is not a Label, 'instanceof' guard will prevent match)
        Color color2 = display.getSystemColor(SWT.COLOR_WIDGET_FOREGROUND);
        fComposite.setForeground(color2);
    }
}
